cd /testbed && PYTHONPATH=/testbed/src python - <<'PY'
import flask

def rejected(name):
    try:
        bp = flask.Blueprint(name, __name__)
    except Exception:
        return True
    app = flask.Flask(__name__)
    try:
        app.register_blueprint(bp)
    except Exception:
        return True
    return False

for name in ['bp.', '.bp', 'a.b', 'a..b']:
    assert rejected(name), f'blueprint name {name!r} containing a dot was accepted'

for name in ['bp', 'bp_2', 'BP']:
    bp = flask.Blueprint(name, __name__)

    @bp.route('/')
    def index():
        return 'ok'

    app = flask.Flask(__name__)
    app.register_blueprint(bp, url_prefix='/' + name)
    with app.test_request_context():
        built = flask.url_for(name + '.index')
    assert built == '/' + name + '/', (name, built)

print('B3 ok')
